# (first ASR segment, last ASR segment, Arabic, English, Chinese) -- times come from asr.json
S = "ﷺ"
CAPS = [
 (0, 1, "في هدأة الليل، يرتفع صراخٌ من غرفة الصغار.", "In the stillness of the night, a scream rises from the children’s room.", "夜深人静时,孩子们的房间里传出一声尖叫。"),
 (2, 3, "تهرع الأم فتجد طفلها جالسًا في فراشه يرتجف،", "The mother rushes in and finds her child sitting up in bed, trembling,", "母亲急忙跑去,发现孩子坐在床上发抖,"),
 (4, 5, "ويشير إلى زاوية الغرفة: هناك شيء!", "pointing to the corner of the room: “There’s something there!”", "指着房间的角落:“那里有东西!”"),
 (6, 6, "تضمّه وتهدّئه،", "She hugs him and calms him,", "她抱住他,安抚他,"),
 (7, 8, "ثم تتكرر القصة في الليلة التالية، والتي بعدها.", "then the story repeats the next night, and the one after.", "可第二天晚上、第三天晚上,同样的事又发生了。"),
 (9, 10, "طفلٌ كان ينام قرير العين، صار يخاف الظلام،", "A child who used to sleep soundly now fears the dark,", "一个原本睡得安稳的孩子,变得害怕黑暗,"),
 (11, 12, "ولا يقبل أن يبقى وحده، ويستيقظ مرات في الليل.", "won’t stay alone, and wakes several times a night.", "不肯独处,夜里醒来好几次。"),
 (13, 13, "إن كانت هذه لياليكم، فهذه الحلقة لكم.", "If these are your nights, this episode is for you.", "如果这就是你们的夜晚,那么这一期就是为你们准备的。"),
 (14, 14, f"سنمشي معًا مع هدي النبي {S} في ليل الأطفال،", "Together we will walk with the Prophet’s guidance (peace be upon him) through a child’s night,", "我们将一起跟随先知(愿主福安之)的指引,走过孩子的夜晚,"),
 (15, 17, "من غروب الشمس، إلى لحظة النوم، إلى اللحظة التي يستيقظ فيها الصغير مذعورًا من حلمٍ مخيف.", "from sunset, to the moment of sleep, to the moment the little one wakes terrified from a bad dream.", "从日落,到入睡,再到孩子从噩梦中惊醒的那一刻。"),
 (18, 18, "نبدأ من ساعة الغروب.", "We begin at the hour of sunset.", "我们从日落时分开始。"),
 (19, 21, f"قال رسول الله {S}: «إذا كان جُنحُ الليل فكُفّوا صبيانكم،", "The Messenger of Allah (peace be upon him) said: “When night falls, keep your children in,", "真主的使者(愿主福安之)说:“当夜幕降临时,把你们的孩子留在家里,"),
 (22, 23, "فإن الشياطين تنتشر حينئذ، فإذا ذهب ساعةٌ من الليل فخلّوهم،", "for the devils spread out at that time; when an hour of the night has passed, let them go,", "因为那时恶魔四处散开;过了一段时间,再放他们出去,"),
 (24, 25, "وأغلقوا الأبواب واذكروا اسم الله، فإن الشيطان لا يفتح بابًا مغلقًا».", "and close the doors and mention Allah’s name, for the devil does not open a closed door.”", "关门时要念真主之名,因为恶魔打不开关着的门。”"),
 (26, 26, "لاحظوا دقّة هذا التوجيه:", "Notice how precise this guidance is:", "请注意这个指引是多么细致:"),
 (27, 27, "لم يأمرنا أن نخاف من الظلام،", "he did not tell us to fear the dark,", "他没有让我们害怕黑暗,"),
 (28, 29, "بل أن نُبقي أطفالنا قريبين منا في تلك الساعة، وأن نغلق بيوتنا باسم الله.", "but to keep our children close at that hour, and to close our homes with the name of Allah.", "而是让我们在那个时刻把孩子留在身边,并奉真主之名关好家门。"),
 (30, 30, "فعند المغرب أدخلوا الصغار إلى البيت،", "So at maghrib, bring the little ones inside,", "所以在昏礼时分,把孩子们带回家里,"),
 (31, 32, "وكلما أغلقتَ بابًا فقل: بسم الله.", "and whenever you close a door, say: “Bismillah.”", "每关一扇门,就念:“奉真主之名。”"),
 (33, 33, "ثم.. بيتٌ لا مبيت فيه للشيطان.", "Then... a home where the devil finds no place to spend the night.", "接着……一个恶魔无处过夜的家。"),
 (34, 34, f"أخبر النبي {S} أن الرجل إذا دخل بيته فذكر الله عند دخوله وعند طعامه،", "The Prophet (peace be upon him) told us that when a man enters his home and mentions Allah on entering and at his meal,", "先知(愿主福安之)告诉我们:一个人进家门时和吃饭时记念真主,"),
 (35, 35, "قال الشيطان لأصحابه: «لا مبيت لكم ولا عشاء».", "the devil says to his companions: “No place to sleep for you, and no supper.”", "恶魔就对同伴说:“你们既没有地方过夜,也没有晚饭吃。”"),
 (36, 37, "علّموا أطفالكم أن يقولوا: بسم الله عند دخول البيت، وبسم الله على المائدة.", "Teach your children to say “Bismillah” when entering the house, and “Bismillah” at the table.", "教孩子们进家门时说“奉真主之名”,吃饭时也说“奉真主之名”。"),
 (38, 38, "عاداتٌ صغيرة، لكنها تحصّن البيت من الداخل.", "Small habits, but they fortify the home from within.", "小小的习惯,却能从内部守护整个家。"),
 (39, 39, f"وأخبر {S} أن الشيطان ينفر من البيت الذي تُقرأ فيه سورة البقرة.", "And he (peace be upon him) told us that the devil flees from a house in which Sūrat al-Baqara is recited.", "他(愿主福安之)还告诉我们,恶魔会逃离诵读《黄牛章》的房子。"),
 (41, 41, "فإن لم تستطع قراءتها كاملةً كل يوم، فأسمِع البيت تلاوتها، ودع الصغير ينشأ على صوت القرآن.", "If you can’t recite all of it every day, let the house hear its recitation, and let the little one grow up with the sound of the Qur’an.", "如果你不能每天读完整章,就让家里播放它的诵读,让孩子在《古兰经》的声音中长大。"),
 (43, 44, "ثم تأتي أهم دقائق الليل: لحظة النوم.", "Then come the most important minutes of the night: bedtime.", "接着是夜里最重要的几分钟:入睡的时刻。"),
 (45, 46, f"قال {S} لأحد أصحابه: «إذا أتيتَ مضجعك فتوضأ وضوءك للصلاة، ثم اضطجع على شقك الأيمن».", "He (peace be upon him) said to one of his Companions: “When you go to bed, make wudūʾ as for prayer, then lie on your right side.”", "他(愿主福安之)对一位圣门弟子说:“你上床时,要像礼拜一样做小净,然后向右侧卧。”"),
 (48, 50, "فإن كان طفلكم كبيرًا فعلّموه ذلك كأنه لعبةٌ لطيفة: وضوء، ثم نومٌ على الجنب الأيمن.", "If your child is older, teach it to him like a gentle game: wudūʾ, then sleeping on the right side.", "如果孩子大一些,就像玩一个温和的游戏那样教他:先做小净,再向右侧睡。"),
 (51, 51, f"وكانت عائشة رضي الله عنها تحكي أن النبي {S} كان إذا أوى إلى فراشه كل ليلةٍ جمع كفّيه،", "ʿĀʾisha (may Allah be pleased with her) related that every night, when the Prophet (peace be upon him) went to bed, he would join his palms,", "阿伊莎(愿主喜悦她)讲述:先知(愿主福安之)每晚上床时,会把双手合在一起,"),
 (52, 54, "ثم نفث فيهما وقرأ الإخلاص والفلق والناس، ثم مسح بهما ما استطاع من جسده، يبدأ برأسه ووجهه، يفعل ذلك ثلاث مرات.", "blow lightly into them and recite al-Ikhlāṣ, al-Falaq and an-Nās, then wipe over as much of his body as he could, starting with his head and face, doing so three times.", "轻轻吹气,诵读《忠诚章》《曙光章》《世人章》,然后用双手尽可能抹遍全身,从头和脸开始,这样做三遍。"),
 (56, 57, "فاجلسوا كل ليلة بجوار سرير الطفل، واقرؤوا الإخلاص والفلق والناس، وانفثوا في أيديكم، وامسحوا برفق على رأسه ووجهه وجسده،", "So sit by your child’s bed each night, recite al-Ikhlāṣ, al-Falaq and an-Nās, blow into your hands, and gently wipe his head, face and body,", "所以每晚坐在孩子床边,诵读《忠诚章》《曙光章》《世人章》,向手中轻吹,再轻轻抹他的头、脸和身体,"),
 (58, 58, "ثلاثًا.", "three times.", "三遍。"),
 (59, 62, "ثم اقرؤوا آية الكرسي، فمن قرأها عند نومه لم يزل عليه من الله حافظ، ولا يقربه شيطانٌ حتى يصبح.", "Then recite Āyat al-Kursī, for whoever recites it at bedtime has a guardian from Allah over him, and no devil comes near him until morning.", "然后诵读《宝座节》,谁在睡前诵读它,就有真主派来的守护者守着他,直到天亮恶魔都不会靠近。"),
 (63, 64, "واقرؤوا خواتيم سورة البقرة، فمن قرأهما في ليلةٍ كفتاه.", "And recite the closing verses of Sūrat al-Baqara, for whoever recites the two in a night, they suffice him.", "再诵读《黄牛章》的末尾两节,谁在夜里诵读它们,它们就足够他用了。"),
 (65, 67, "وفي الختام، قولوا في أذنه بهدوء، أو قولوها معه إن كان كبيرًا:", "And to finish, say softly in his ear, or say it with him if he is older:", "最后,在他耳边轻声说,或者孩子大了就和他一起说:"),
 (68, 68, "«باسمك اللهم أموت وأحيا».", "“In Your name, O Allah, I die and I live.”", "“主啊,奉您的名,我死,我生。”"),
 (69, 69, "قد تتحول هذه الدقائق إلى أحبّ لحظات يومه:", "These minutes may become the most beloved moments of his day:", "这几分钟可能会成为他一天中最喜爱的时光:"),
 (70, 71, "صوت أمه، ويدٌ تمسح على رأسه، وكلماتٌ تذكّره بالله.", "his mother’s voice, a hand stroking his head, and words that remind him of Allah.", "妈妈的声音,一只抚摸他头的手,还有让他记起真主的话语。"),
 (72, 72, "فإذا استيقظ مذعورًا..", "And if he wakes up frightened...", "如果他惊醒了……"),
 (73, 75, f"قال {S}: «الرؤيا الصالحة من الله، والحُلُم من الشيطان».", "He (peace be upon him) said: “A good dream is from Allah, and a bad dream is from the devil.”", "他(愿主福安之)说:“好梦来自真主,噩梦来自恶魔。”"),
 (76, 77, "وعلّمنا ما نفعل إذا رأينا ما نكره: أن ننفث عن يسارنا ثلاثًا، ونستعيذ بالله من الشيطان ثلاثًا، ونتحوّل عن الجنب الذي كنا عليه،", "And he taught us what to do when we see what we dislike: blow lightly to our left three times, seek refuge in Allah from the devil three times, and turn from the side we were lying on,", "他还教我们看到不喜欢的梦时该怎么做:向左边轻吹三次,三次求真主护佑远离恶魔,并翻身换到另一侧,"),
 (78, 78, "ولا نحدّث بها أحدًا، فإنها لن تضره.", "and not tell anyone about it, for it will not harm him.", "也不要把它告诉任何人,这样它就不会伤害他。"),
 (79, 80, "فإذا فزع صغيرك من نومه، ضمّه أولًا وهدّئ رَوعه،", "If your little one wakes in fright, hug him first and calm his fear,", "如果孩子从睡梦中惊醒,先抱住他,平复他的恐惧,"),
 (81, 82, "ثم قولا معًا ثلاثًا: أعوذ بالله من الشيطان الرجيم.", "then say together three times: “I seek refuge in Allah from the accursed devil.”", "然后一起说三遍:“我求真主护佑,免遭被驱逐的恶魔之害。”"),
 (83, 84, "وانفثا عن اليسار نفثًا خفيفًا، ثم اقلبه على جنبه الآخر،", "Blow lightly to the left, then turn him onto his other side,", "向左边轻轻吹气,然后帮他翻到另一侧,"),
 (85, 85, "وأعِد عليه آية الكرسي والمعوّذات.", "and recite Āyat al-Kursī and the Muʿawwidhāt over him again.", "再为他诵读《宝座节》和护佑三章。"),
 (86, 89, "وقل: هذا الحلم من الشيطان، والله أقوى من كل شيء، ولن يستطيع أن يؤذيك.", "And say: “This dream is from the devil; Allah is stronger than everything, and it cannot hurt you.”", "并对他说:“这个梦来自恶魔,真主比一切都强大,它伤害不了你。”"),
 (90, 91, "ولا تكثر من سؤاله عن تفاصيل الحلم، بل اصرف قلبه إلى الله.", "Don’t keep asking him about the details of the dream; instead, turn his heart to Allah.", "不要一直追问梦的细节,而要把他的心引向真主。"),
 (92, 93, f"ودعاءٌ للأمان من الفزع: رُوي أن النبي {S} علّم هذا الدعاء لمن يفزع في نومه،", "And a supplication for safety from fright: it is reported that the Prophet (peace be upon him) taught this supplication to one who is frightened in his sleep,", "还有一个免于惊恐的祈祷:据传先知(愿主福安之)把这段祈祷词教给睡梦中受惊的人,"),
 (94, 94, "وكان عبد الله بن عمرو يعلّمه أبناءه: «أعوذ بكلمات الله التامة من غضبه وعقابه وشرّ عباده، ومن همزات الشياطين وأن يحضرون».", "and ʿAbdullāh ibn ʿAmr used to teach it to his sons: “I seek refuge in the perfect words of Allah from His anger and punishment, from the evil of His servants, and from the whisperings of the devils and from their presence.”", "阿卜杜拉·本·阿慕尔常把它教给自己的儿子们:“我借真主完美的言辞求护佑,免遭他的恼怒和惩罚,免遭他的仆人之恶,免遭恶魔的唆使和它们的到来。”"),
 (95, 97, "ومعه التعويذة التي كان يعوّذ بها الحسن والحسين: «أعيذك بكلمات الله التامة من كل شيطانٍ وهامّة، ومن كل عينٍ لامّة».", "Along with the words he used to protect al-Ḥasan and al-Ḥusayn: “I seek refuge for you in the perfect words of Allah from every devil and harmful creature, and from every evil eye.”", "以及他为哈桑和侯赛因求护佑的话:“我借真主完美的言辞为你求护佑,远离一切恶魔、一切毒虫和一切邪眼。”"),
 (98, 99, "ولنكن صادقين مع أنفسنا: أحيانًا نحن من يكبّر الخوف في قلوب أطفالنا.", "Let’s be honest with ourselves: sometimes we are the ones who make fear grow in our children’s hearts.", "让我们对自己诚实:有时恰恰是我们让孩子心中的恐惧变大。"),
 (100, 101, "أولًا: لا تخوّفوا الأطفال بالجن والغول والبعبع.", "First: don’t frighten children with jinn, ghouls and bogeymen.", "第一:不要用精灵、妖怪和怪物吓唬孩子。"),
 (102, 103, "حين نقول للصغير لنُسكته: سيأتي الجني! فإننا نزرع في قلبه الخوف ذاته الذي يوقظه في الليل.", "When we tell a little one, to quiet him, “The jinn is coming!”, we plant in his heart the very fear that wakes him at night.", "当我们为了让孩子安静而说“精灵要来了!”,就是在他心里种下那份让他夜里惊醒的恐惧。"),
 (105, 107, "قولوا له بدلًا من ذلك: الله يحفظنا، وآية الكرسي تحرسنا.", "Tell him instead: “Allah protects us, and Āyat al-Kursī guards us.”", "反而要对他说:“真主保护我们,《宝座节》守护我们。”"),
 (109, 109, f"ثانيًا: كان النبي {S} رفيقًا بالصغار،", "Second: the Prophet (peace be upon him) was gentle with children.", "第二:先知(愿主福安之)对孩子十分温和,"),
 (110, 113, "قال لابن عباس وهو غلام: «يا غلام، إني أعلمك كلمات: احفظ الله يحفظك».", "He said to Ibn ʿAbbās when he was a boy: “Young man, I will teach you some words: be mindful of Allah, and He will protect you.”", "他对还是少年的伊本·阿拔斯说:“孩子,我教你几句话:你谨守真主,真主就会保护你。”"),
 (114, 115, "بالحب يخاطب الطفل، وبالله يربط قلبه.", "He addresses the child with love, and ties his heart to Allah.", "他用爱与孩子说话,把孩子的心与真主连在一起。"),
 (116, 117, "ثالثًا: سكينة البيت.", "Third: a calm home.", "第三:家的安宁。"),
 (118, 118, "الطفل الذي ينام على أصوات الشجار لا ينام مطمئنًا.", "A child who falls asleep to the sound of quarrels does not sleep at peace.", "在争吵声中入睡的孩子,睡不安稳。"),
 (119, 119, "قال تعالى: ﴿أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ﴾", "Allah says: “Verily, in the remembrance of Allah do hearts find rest.”", "真主说:“真的,记念真主,心才能安宁。”"),
 (120, 121, "والبيت الذي يُذكر فيه الله تطمئن فيه القلوب.", "And a home in which Allah is remembered is a home where hearts find rest.", "记念真主的家,人心就会安宁。"),
 (122, 123, f"وإن اشتدّ خوف الطفل وطال، فتذكّروا قوله {S}: «تداووا عباد الله».", "And if the child’s fear becomes severe and lasts long, remember his saying (peace be upon him): “Seek treatment, servants of Allah.”", "如果孩子的恐惧加重并持续很久,请记住他(愿主福安之)的话:“真主的仆人们,你们要就医。”"),
 (124, 124, "فالرقية والذكر يسيران مع سائر الأسباب، لا يحلّان محلّها.", "Ruqyah and dhikr go along with all other means; they do not replace them.", "诵经祛病和赞念与其他一切措施并行,而不是取代它们。"),
 (125, 125, "وإليكم برنامج الليل باختصار:", "Here is the night plan in brief:", "下面简要总结夜间方案:"),
 (126, 129, "عند الغروب: أبقوا الصغار في البيت، وأغلقوا الأبواب بقول: بسم الله، وعلى العشاء: بسم الله.", "At sunset: keep the little ones home, close the doors saying “Bismillah”, and at supper: “Bismillah”.", "日落时:让孩子待在家里,关门时念“奉真主之名”,吃晚饭时也念“奉真主之名”。"),
 (130, 131, "وقبل النوم: وضوء، ونومٌ على الجنب الأيمن، وبجوار السرير المعوّذات مع النفث والمسح ثلاثًا،", "Before sleep: wudūʾ, sleeping on the right side, and by the bed, the Muʿawwidhāt with blowing and wiping three times,", "睡前:做小净,向右侧卧,在床边诵读护佑三章,轻吹并抚摸三遍,"),
 (132, 133, "ثم آية الكرسي وخواتيم البقرة، ثم: باسمك اللهم أموت وأحيا.", "then Āyat al-Kursī and the end of al-Baqara, then: “In Your name, O Allah, I die and I live.”", "然后诵读《宝座节》和《黄牛章》末尾,再说:“主啊,奉您的名,我死,我生。”"),
 (135, 139, "وإن استيقظ فزعًا: حضنٌ، واستعاذةٌ ثلاثًا، ونفثٌ عن اليسار، وتحويلٌ للجنب، وإعادةٌ لآية الكرسي.", "And if he wakes in fright: a hug, seeking refuge three times, blowing to the left, turning onto the other side, and reciting Āyat al-Kursī again.", "如果他惊醒:拥抱他,三次求护佑,向左轻吹,翻身换侧,再诵读一遍《宝座节》。"),
 (141, 144, "طفلك أمانةٌ بين يديك، وحين تُغمض عيناه في الليل لا يبقى معه إلا الذكر الذي قرأته عليه.", "Your child is a trust in your hands, and when his eyes close at night, nothing stays with him but the dhikr you recited over him.", "孩子是你手中的托付;当他夜里闭上双眼,陪伴他的只有你为他诵读的赞念。"),
 (145, 147, "فاجلس الليلة بجوار سريره، وامسح على رأسه، واستودعه خير حافظ: الله.", "So sit by his bed tonight, stroke his head, and entrust him to the best Protector: Allah.", "所以今晚就坐在他的床边,抚摸他的头,把他托付给最好的保护者——真主。"),
 (148, 148, "شارك هذا المقطع مع كل أبٍ وأمٍّ أتعبهم السهر،", "Share this clip with every father and mother worn out by sleepless nights,", "把这段视频分享给每一位被熬夜折磨的父亲和母亲,"),
 (149, 149, "واكتب في التعليقات: اللهم اجعل ليالي أطفالنا سكينةً وأمانًا.", "and write in the comments: “O Allah, make our children’s nights peaceful and safe.”", "并在评论中写下:“真主啊,求您让我们孩子的夜晚安宁而平安。”"),
 (150, 150, "آمين.", "Amen.", "阿敏。"),
]
